def sort_age(lst):
    if len(lst) == 0:
        return []
    elif len(lst) == 1:
        return lst
    else:
        mid = len(lst) // 2
        lst1 = sort_age(lst[:mid])
        lst2 = sort_age(lst[mid:])

        result = []
        i, j = 0, 0
        while i < len(lst1) and j < len(lst2):
            if lst1[i][1] >= lst2[j][1]:
                result.append(lst1[i])
                i += 1
            else:
                result.append(lst2[j])
                j += 1
        result.extend(lst1[i:])
        result.extend(lst2[j:])

        return result

