def sort_age(lst):
    """selection sort"""
    l = len(lst)
    for i in range(l):
        largest = lst[i]
        largest_idx = i
        for j in range(i+1,l):
            if lst[j][1] > largest[1]:
                largest = lst[j] #assign new largest value
                largest_idx = j
        lst[i],lst[largest_idx] = lst[largest_idx],lst[i] #swap positions if larger
    return lst

