    while lst:
        oldest = lst[0]
        for person in lst:
            if person[1] >= oldest[1]:
                oldest = person
        lst.remove(oldest)
        sort.append(oldest)
    return sort

def sort_age(lst):
    for j in range(len(lst)-1):
        for i in range(len(lst)-1-j):
            if lst[i][1] < lst[i+1][1]:
                lst[i], lst[i+1] = lst[i+1], lst[i]
    return lst

