def sort_age(lst):
    sorted = []
    while lst:
        oldest = lst[0]
        oldest_idx = 0
        for i in range(len(lst)):
            if lst[i][1] > oldest[1]:
                oldest = lst[i]
                oldest_idx = i
        sorted.append(lst.pop(oldest_idx))
    return sorted

