def sort_age(lst):
    for i in range(1, len(lst)):
        while i > 0 and lst[i][1] < lst[i-1][1]:
            temp = lst[i]
            lst[i] = lst[i-1]
            lst[i-1] = temp
            i -= 1
    lst.reverse()
    return lst

def sort_age(lst):
